detaileddescription.para:
Example: for(inti=0;i<7;++i)//Canonicalloop"i"
for(intj=0;j<9;++j)//Canonicalloop"j"
body(i,j);

After collapsing with Loops={i,j}, the loop is changed to for(intij=0;ij<63;++ij){
inti=ij/9;
intj=ij%9;
body(i,j);
}

Example: for(inti=0;i<15;++i)//Canonicalloop"i"
for(intj=0;j<14;++j)//Canonicalloop"j"
body(i,j);

After tiling with Loops={i,j} and TileSizes={5,7}, the loop is changed to for(inti1=0;i1<3;++i1)
for(intj1=0;j1<2;++j1)
for(inti2=0;i2<5;++i2)
for(intj2=0;j2<7;++j2)
body(i1*3+i2,j1*3+j2);

void contiguous_partial_reduce(void *reduce_data,
                          kmp_ShuffleReductFctPtr ShuffleReduceFn,
                          int size, int lane_id) { int curr_size; int offset; curr_size = size; mask = curr_size/2; while (offset>0) { ShuffleReduceFn(reduce_data, lane_id, offset, 1); curr_size = (curr_size+1)/2; offset = curr_size/2; } }

The code generation follows the pattern in the example below. void.omp_mapper.<type_name>.<mapper_id>.(void*rt_mapper_handle,
void*base,void*begin,
int64_tsize,int64_ttype,
void*name=nullptr){
//Allocatespaceforanarraysectionfirstoraddabase/beginfor
//pointerdereference.
if((size>1||(base!=begin&&maptype.IsPtrAndObj))&&
!maptype.IsDelete)
__tgt_push_mapper_component(rt_mapper_handle,base,begin,
size*sizeof(Ty),clearToFromMember(type));
//Mapmembers.
for(unsignedi=0;i<size;i++){
//Foreachcomponentspecifiedbythismapper:
for(autoc:begin[i]->all_components){
if(c.hasMapper())
(*c.Mapper())(rt_mapper_handle,c.arg_base,c.arg_begin,
c.arg_size,
c.arg_type,c.arg_name);
else
__tgt_push_mapper_component(rt_mapper_handle,c.arg_base,
c.arg_begin,c.arg_size,c.arg_type,
c.arg_name);
}
}
//Deletethearraysection.
if(size>1&&maptype.IsDelete)
__tgt_push_mapper_component(rt_mapper_handle,base,begin,
size*sizeof(Ty),clearToFromMember(type));
}
